package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.RandomStringUtils#randomAscii(int)
 */
public class RandomStringUtils_randomAscii_TriageGen1Test {

    @Test
    public void testRandomAscii_PositiveCount() {
        int count = 10;
        String result = RandomStringUtils.randomAscii(count);
        assertNotNull("The returned string should not be null", result);
        assertEquals("The length of the string should match the requested count", count, result.length());

        // Verify that all characters are within the ASCII range 32 to 126 (inclusive)
        // Note: The method calls random(count, 32, 127, false, false) 
        // where 127 is the exclusive upper bound.
        for (int i = 0; i < result.length(); i++) {
            char c = result.charAt(i);
            assertTrue("Character at index " + i + " should be in ASCII range [32, 127)", (int) c >= 32 && (int) c < 127);
        }
    }

    @Test
    public void testRandomAscii_ZeroCount() {
        int count = 0;
        String result = RandomStringUtils.randomAscii(count);
        assertNotNull(result);
        assertEquals("The length of the string should be 0 when count is 0", 0, result.length());
    }

    @Test
    public void testRandomAscii_NegativeCount() {
        int count = -5;
        String result = RandomStringUtils.randomAscii(count);
        assertNotNull(result);
        assertEquals("The length of the string should be 0 when count is negative", 0, result.length());
    }

    @Test
    public void testRandomAscii_LargeCount() {
        int count = 1000;
        String result = RandomStringUtils.randomAscii(count);
        assertNotNull(result);
        assertEquals(count, result.length());
    }

    @Test
    public void testRandomAscii_Uniqueness() {
        // Statistical test to ensure it's actually random and not returning a constant string
        int count = 50;
        String result1 = RandomStringUtils.randomAscii(count);
        String result2 = RandomStringUtils.randomAscii(count);

        assertNotEquals("Two consecutive calls should likely produce different strings", result1, result2);
    }
}
